import { useEffect, useState } from 'react';
import api from '../api/api';

export default function Dashboard() {
  const [bookings, setBookings] = useState([]);

  useEffect(() => {
    api.get('/bookings/my').then(({ data }) => setBookings(data));
  }, []);

  const handleCancel = async (bookingId) => {
    await api.put(`/bookings/${bookingId}/cancel`);
    setBookings((prev) => prev.map((b) => (b._id === bookingId ? { ...b, status: 'cancelled' } : b)));
  };

  return (
    <div className="dashboard">
      <h2>My bookings</h2>
      {bookings.length === 0 && <p>No bookings yet.</p>}
      {bookings.map((b) => (
        <div key={b._id} className="booking-row">
          <p>{b.station?.name} · {b.date} · {b.startTime}-{b.endTime}</p>
          <p>Status: {b.status} · ₹{b.estimatedCost}</p>
          {b.status === 'confirmed' && (
            <button onClick={() => handleCancel(b._id)}>Cancel</button>
          )}
        </div>
      ))}
    </div>
  );
}
